// Code node «Звіт на вимогу» — /report (owner only): today's daily report right now, to the owner who asked.
// Input: rows of the «Журнал» sheet. report-lib (RL) is inlined above by the build.
const msg = $('Telegram Trigger').first().json.message || {};
const chatId = String((msg.chat && msg.chat.id) ?? '');
const cook = $('Кухар').first().json.cook || {};
if (cook.role !== 'owner') return [{ json: { chat_id: chatId, reply: 'ℹ️ Команда /report доступна лише власнику мережі.' } }];
const readErr = $input.all().find((i) => i.json && i.json.error);
if (readErr) throw new Error('Журнал: ' + readErr.json.error);
const rows = $input.all().map((i) => i.json);
const t = RL.today();
const reply = '🗓 Щоденний звіт\n\n' + RL.networkReport(RL.filterRows(rows, { from: t }), 'за сьогодні (' + t + ')');
return [{ json: { chat_id: chatId, reply: reply.slice(0, 3900) } }];

// Code node «Скинути кеш» — /reload (owner only): forget the cached recipe cards and cook list,
// so edits in the sheet apply at once instead of within 5–10 minutes.
const msg = $('Telegram Trigger').first().json.message || {};
const chatId = String((msg.chat && msg.chat.id) ?? '');
const cook = $('Кухар').first().json.cook || {};
if (cook.role !== 'owner') return [{ json: { chat_id: chatId, reply: 'ℹ️ Команда /reload доступна лише власнику мережі.' } }];
const sd = $getWorkflowStaticData('global');
delete sd.cards; delete sd.cooks;
return [{ json: { chat_id: chatId, reply: '🔄 Кеш скинуто: наступне повідомлення прочитає техкарти й список кухарів із таблиці заново.' } }];

// Code node «Точка» — «📍 Точка», «/point» or «/point V2»: show the kitchen buttons or switch the sender's kitchen.
// Input: rows of the «Точки» sheet. Output: { action: menu | set | deny, chat_id, reply, venue_id?, venue? }.
// The owner may switch to any active kitchen; others only to the kitchens in their allowed_venues column.
const readErr = $input.all().find((i) => i.json && i.json.error);
if (readErr) throw new Error('Точки: ' + readErr.json.error);
const msg = $('Telegram Trigger').first().json.message || {};
const cook = $('Кухар').first().json.cook || {};
// the sender's Telegram user ID — the key of their row in «Кухарі»
const chatId = cook.chat_id || String((msg.from && msg.from.id) ?? (msg.chat && msg.chat.id) ?? '');
const isActive = (v) => v === true || ['TRUE', '1', 'ТАК', 'YES'].includes(String(v ?? '').trim().toUpperCase());
const venues = $input.all().map((i) => i.json)
  .filter((v) => v && v.venue_id && isActive(v.active))
  .map((v) => ({ id: String(v.venue_id).trim().toUpperCase(), name: String(v.name || v.venue_id) }));
const allowedIds = cook.role === 'owner' ? venues.map((v) => v.id) : (cook.allowed || []);
const current = venues.find((v) => v.id === cook.venue_id);
const now = '📍 Зараз ваші перевірки йдуть у ' + (current ? current.id + ' · ' + current.name : (cook.venue_id || '—')) + '.';

const m = String(msg.text || '').match(/(?:^|\s|📍)\s*[vв]\s?(\d{1,2})(?!\d)/i);
const want = m ? 'V' + Number(m[1]) : null;
if (!want) {
  if (allowedIds.length < 2) return [{ json: { action: 'deny', chat_id: chatId, reply: now + '\nВас закріплено за цією точкою. Якщо вас перевели на іншу — попросіть адміністратора змінити її у списку кухарів.' } }];
  const list = venues.filter((v) => allowedIds.includes(v.id)).map((v) => (v.id === cook.venue_id ? '• ' : '  ') + v.id + ' · ' + v.name);
  return [{ json: { action: 'menu', chat_id: chatId, reply: now + '\n\nОберіть точку кнопкою нижче:\n' + list.join('\n') } }];
}
const target = venues.find((v) => v.id === want);
if (!target) return [{ json: { action: 'deny', chat_id: chatId, reply: 'Точки ' + want + ' немає серед активних у листі «Точки».' } }];
if (!allowedIds.includes(want)) return [{ json: { action: 'deny', chat_id: chatId, reply: '⛔ Ви не можете надсилати перевірки від імені ' + want + '. ' + now } }];
if (want === cook.venue_id) return [{ json: { action: 'deny', chat_id: chatId, reply: now + ' Нічого не змінено.' } }];
const sd = $getWorkflowStaticData('global');
delete sd.cooks; // the cook list changes — re-read it on the next message
return [{ json: { action: 'set', chat_id: chatId, venue_id: target.id, venue: target.name,
  reply: '✅ Точку змінено: тепер ваші перевірки йдуть у ' + target.id + ' · ' + target.name + '.\nЩоб повернутися — «📍 Точка».' } }];

// Code node «Підпис → кандидат» — runs once for all items. Input: rows of the «Техкарти» sheet, or one
// {fresh: true} item when the cached cards (workflow static data, refreshed every 10 minutes or by /reload) are valid.
// Picks the kitchen (profile or a code in the caption, with the lock check), matches the cook's caption to a recipe
// card, parses portions («х2»), checks for a re-sent photo and builds the Vision prompt.
// Output: one item with the photo binary passed through; a non-empty stop_reply means «answer this, log nothing».

const sd = $getWorkflowStaticData('global');
const inRows = $input.all().map(i => i.json);
const readErr = inRows.find(r => r && r.error);
if (readErr) throw new Error('Техкарти: ' + readErr.error);
let sheetRows;
if (inRows.some(r => r && r.dish_id)) { sheetRows = inRows; sd.cards = { at: Date.now(), rows: inRows }; }
else if (sd.cards && sd.cards.rows) sheetRows = sd.cards.rows;
else throw new Error('Техкарти: немає даних');

const trig = $('Telegram Trigger').first();
const msg = trig.json.message || {};
const rawCaption = String(msg.caption || '').trim();
let cook = null;
try { cook = $('Кухар').first().json.cook || null; } catch (e) { /* only in offline tests */ }

// Which kitchen gets this check. By default — the kitchen in the sender's profile (Telegram ID → «Кухарі»).
// A kitchen code in the caption («R02 V3») sends this one check elsewhere, but only for the owner and for people
// who have that kitchen in allowed_venues. A cook locked to one kitchen who writes another kitchen's code gets a
// warning and nothing is logged — so the wrong kitchen's statistics are not spoiled and no duplicate appears later.
const VENUE_RE = /(?:^|[\s,;:(])📍?\s*[VvВв](\d{1,2})(?![\d\p{L}])/u;
const vm = rawCaption.match(VENUE_RE);
const wantVenue = vm ? 'V' + Number(vm[1]) : null;
let venueId = cook ? cook.venue_id : '', venueName = cook ? cook.venue : '', stopReply = '';
if (cook) {
  const known = cook.venues && cook.venues.length ? cook.venues : null;
  const own = cook.venue_id + (cook.venue ? ' · ' + cook.venue : '');
  const target = known && wantVenue ? known.find((v) => v.id === wantVenue) : null;
  if (cook.venue_ok === false) {
    stopReply = '⛔ Ваш профіль не прив\'язано до активної точки (у листі «Кухарі»: «' + (cook.venue_id || '—') + '»).\nПеревірку не записано — зверніться до адміністратора.';
  } else if (wantVenue && wantVenue !== cook.venue_id) {
    if (known && !target) stopReply = '⛔ Точки ' + wantVenue + ' немає серед активних.\nПеревірку не записано. Надішліть фото без коду точки — воно піде у вашу точку (' + own + ').';
    else if (cook.role === 'owner' || (cook.allowed || []).includes(wantVenue)) { venueId = wantVenue; venueName = target ? target.name : wantVenue; }
    else stopReply = '⛔ Ви закріплені за точкою ' + own + ', а в підписі вказано ' + wantVenue + (target ? ' · ' + target.name : '') + '.\n'
      + 'Перевірку не записано, щоб не зіпсувати статистику точок. Надішліть фото ще раз без коду точки — воно піде у вашу точку.';
  }
}

const isActive = v => v === true || ['TRUE', '1', 'ТАК', 'YES'].includes(String(v ?? '').trim().toUpperCase());
const num = v => (v === '' || v == null) ? NaN : Number(String(v).replace(',', '.'));
const cards = sheetRows
  .filter(c => c && c.dish_id && c.dish_name && isActive(c.active))
  .map(c => ({
    dish_id: String(c.dish_id).trim().toUpperCase(),
    dish_name: String(c.dish_name).trim(),
    aliases: String(c.aliases || ''),
    category: String(c.category || ''),
    norm_grams: num(c.norm_grams),
    tol_under: num(c.tol_under_pct ?? c.tolerance_pct),
    tol_over: num(c.tol_over_pct ?? c.tolerance_pct),
    pack_grams: Number.isFinite(num(c.pack_grams)) ? num(c.pack_grams) : 0,
    must_have: String(c.must_have || c.visual_features || ''),
    may_vary: String(c.may_vary || ''),
  }))
  .filter(c => Number.isFinite(c.norm_grams) && c.norm_grams > 0);
if (!cards.length) throw new Error('Техкарти: немає жодної активної позиції');

// Portions: «х2», «x2», «2х», «2 порції» → the norm is multiplied.
const PORTIONS_RE = /(?:^|\s)(?:[xх×*]\s?(\d{1,2})|(\d{1,2})\s?[xх×])(?=\s|$)|(\d{1,2})\s*(?:порц\S*|porc\S*)/i;
const noVenue = vm ? rawCaption.replace(VENUE_RE, ' ').trim() : rawCaption;
const pm = noVenue.match(PORTIONS_RE);
const pn = pm ? Number(pm[1] || pm[2] || pm[3]) : 1;
const portions = pn >= 1 && pn <= 10 ? pn : 1;
const caption = pm ? noVenue.replace(PORTIONS_RE, ' ').trim() : noVenue;

// Ukrainian and Russian spellings fold to one form: «Філадельфія» = «Филадельфия», «Зелений» = «Зеленый».
const norm = s => String(s || '').toLowerCase()
  .replace(/[іїийы]/g, 'и').replace(/[єэё]/g, 'е').replace(/ґ/g, 'г').replace(/[ьъ'’`]/g, '')
  .replace(/[^a-zа-я0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
const toks = s => norm(s).split(' ').filter(w => w.length >= 3 && !/\d/.test(w));
const names = c => [c.dish_name].concat(c.aliases.split(';')).map(norm).filter(Boolean);
const sameWord = (w, x) => x === w || x.startsWith(w) || w.startsWith(x) || (w.length >= 4 && x.includes(w));

let card = null, captionCandidates = [], normFromCaption = null, idGiven = false;
if (caption) {
  const capN = norm(caption);
  const idm = caption.match(/(?:^|[^a-zа-яіїєґ])[rр]\s?-?(\d{1,3})(?!\d)/i);
  if (idm) { idGiven = true; const id = 'R' + String(Number(idm[1])).padStart(2, '0'); card = cards.find(c => c.dish_id === id) || null; }
  if (!card) card = cards.find(c => names(c).includes(capN)) || null;
  if (!card) {
    const capW = toks(caption);
    if (capW.length) {
      const need = Math.max(1, Math.ceil(capW.length * 0.5));
      let bestS = 0, best = [];
      for (const c of cards) {
        const nt = names(c).flatMap(n => n.split(' ')).filter(w => w.length >= 3);
        let s = 0; for (const w of capW) if (nt.some(x => sameWord(w, x))) s++;
        if (s > bestS) { bestS = s; best = [c]; } else if (s === bestS && s > 0) best.push(c);
      }
      if (bestS >= need) { if (best.length === 1) card = best[0]; else captionCandidates = best.map(c => c.dish_id); }
    }
  }
  if (!card && !captionCandidates.length && !idGiven) {
    const gm = caption.match(/(\d{2,4})(?:[.,]\d+)?\s*(?:г|гр|g)?(?![\d])/i);
    if (gm) { const n = Number(gm[1]); if (n >= 20 && n <= 5000) normFromCaption = n; }
  }
}

// Same photo FILE sent again? Telegram gives every new camera shot its own file_unique_id, so identical-looking
// portions never collide — only a re-sent file does. A re-sent file with a different caption (or after an
// unfinished check) is a correction and is checked again; the same file with the same caption after a final
// verdict is stopped. Entries are recorded by «Вердикт».
const photos = msg.photo || [];
const photoUid = String((photos.length ? photos[photos.length - 1].file_unique_id : (msg.document && msg.document.file_unique_id)) || '');
const seenRaw = photoUid ? (sd.seen || {})[photoUid] : null;
// older records are a bare timestamp without caption or verdict — treat them as unfinished, so they can be re-checked
const seen = seenRaw ? (typeof seenRaw === 'string' ? { ts: seenRaw, caption: null, final: false } : seenRaw) : null;
const sameCaption = seen && (seen.caption === null || norm(seen.caption) === norm(rawCaption));
const duplicateOf = !stopReply && seen && seen.final && sameCaption ? seen.ts : '';
const recheckOf = seen && !duplicateOf ? seen.ts : '';
if (duplicateOf) stopReply = '♻️ Це саме фото з тим самим підписом уже перевіряли (' + duplicateOf + ').\n'
  + 'Нова порція — сфотографуйте її ще раз. Помилилися з підписом — надішліть це фото з правильним підписом, і бот перевірить його знову.';

const base = 'Ти допомагаєш кухні ресторану контролювати вагу порцій: на фото — страва, яку кухар зважив на кухонних вагах. '
  + '1) Дисплей ваг: перепиши показання у display_text (з крапкою чи комою, напр. 384.8 або 0.410) і поверни число в display_value. '
  + 'unit — g або kg (позначка kg або число на кшталт 0.410 — це kg). '
  + 'digits_confidence від 0 до 1 — наскільки чітко видно кожну цифру. Якщо фото розмите, стиснуте, під кутом або цифри частково закриті бліком — низька впевненість; не вгадуй цифри. '
  + 'Якщо ваг або дисплея на фото немає — це нормально: readable=false, display_value=null, решту полів заповни. '
  + '2) Коротко опиши страву українською (looks_like): тип (рол / макі / нігірі / гункан / сет / поке), що зверху, колір, сира риба чи запечена / у клярі. '
  + '3) in_container — true, якщо страва лежить у контейнері, коробці чи мисці.';
const check = card
  ? ' 4) Кухар підписав фото як «' + card.dish_name + '». Ключові ознаки цієї страви: ' + card.must_have + '. '
    + 'Допустимі відмінності (НЕ причина невідповідності): ' + (card.may_vary || '—') + '; також будь-який додатковий гарнір, соус, зелень, посипка чи упаковка. '
    + 'visual_match=false, якщо частину страви, де має бути ключова ознака, ВИДНО, але там інше (інша риба чи топінг, інше покриття, запечене замість сирого, інший тип страви). '
    + 'visual_match=null лише якщо цю частину страви НЕ видно на фото (закрито, поза кадром, надто темно). '
    + 'visual_confidence від 0 до 1 — наскільки ти впевнений у visual_match.'
  : ' 4) Підпису зі стравою немає: visual_match=null.';
const fmt = ' Відповідай ЛИШЕ валідним JSON одним рядком без markdown: {"display_text": "<як на дисплеї>", "display_value": <число або null>, "unit": "g|kg", "digits_confidence": <0..1>, "readable": <true|false>, "in_container": <true|false>, "looks_like": "<короткий опис>", "visual_match": <true|false|null>, "visual_confidence": <0..1>, "visual_reason": "<коротко чому, або порожньо>"}.';
// Shorter wording for the second attempt, so a refusal of the first prompt is not simply repeated.
const retryPrompt = 'Фото з кухні ресторану: порція страви на кухонних вагах (ваг може й не бути в кадрі). '
  + 'Відповідай ЛИШЕ JSON одним рядком: {"display_text": "<цифри на дисплеї або порожньо>", "display_value": <число або null>, "unit": "g|kg", "digits_confidence": <0..1>, "readable": <true якщо цифри видно>, "in_container": <true|false>, "looks_like": "<що за страва, українською>", '
  + (card ? '"visual_match": <true якщо схоже на «' + card.dish_name + '» (' + card.must_have + '), false якщо видно, що ні, null якщо не видно>, "visual_confidence": <0..1>, "visual_reason": "<коротко>"}.'
    : '"visual_match": null, "visual_confidence": 0, "visual_reason": ""}.');

return [{
  json: {
    caption: rawCaption, card, portions,
    match_source: card ? 'caption' : (normFromCaption ? 'norm' : ''),
    caption_candidates: captionCandidates, norm_from_caption: normFromCaption,
    photo_uid: photoUid, duplicate_of: duplicateOf, recheck_of: recheckOf,
    venue_id: venueId, venue: venueName, stop_reply: stopReply,
    cards, vision_prompt: base + check + fmt, vision_prompt_retry: retryPrompt,
  },
  binary: trig.binary,
}];

// Code node «Вердикт» — runs once for all items (input: the OpenAI Vision answer).
// Turns the Vision reading into a verdict and the reply text. Output: one journal row (+ reply, chat_id).
//   OK · UNDER (underweight) · OVER (overweight) · MISMATCH (photo ≠ caption) · RECHECK (digits unclear /
//   implausible deviation) · LOWCONF · UNREADABLE

const N = '\n';
const DEFAULT_UNDER = 2.9; // % — allowed underweight when a card has none, and for «Тех карта N» captions
const DEFAULT_OVER = 5;    // % — allowed overweight (softer: the customer is not short-changed)
const PLAUSIBLE = 30;      // % — a bigger deviation is more likely a misread, a container or several portions
const MIN_DIGITS = 0.6;    // below this digits_confidence the weight is not trusted
const MIN_VISUAL = 0.7;    // MISMATCH only when Vision is at least this sure

const pre = $('Підпис → кандидат').first().json;
const msg = $('Telegram Trigger').first().json.message || {};
const cook = $('Кухар').first().json.cook || {};
const cards = pre.cards || [];
const portions = pre.portions || 1;

// ---- Vision answer ----
const v = $input.first().json || {};
const vt = typeof v === 'string' ? v : (v.content ?? v.text ?? v.output ?? (v.message && v.message.content) ?? JSON.stringify(v));
let vp = {}; try { const m = String(vt).match(/\{[\s\S]*\}/); if (m) vp = JSON.parse(m[0]); } catch (e) {}
const visionEmpty = !('display_value' in vp) && !('scale_grams' in vp) && !('readable' in vp);
const toNum = x => Number(String(x ?? '').replace(',', '.'));
let value = toNum(vp.display_value ?? vp.scale_grams);
if (vp.display_value == null && vp.scale_grams == null || !Number.isFinite(value) || value <= 0) value = null;
const unit = String(vp.unit || '').toLowerCase();
const digitsConf = Number.isFinite(toNum(vp.digits_confidence)) && vp.digits_confidence !== null && vp.digits_confidence !== '' ? toNum(vp.digits_confidence) : 0.8;
const inContainer = vp.in_container === true;
const looks = String(vp.looks_like || '').slice(0, 200);
const vmatch = vp.visual_match === true ? true : (vp.visual_match === false ? false : null);
const vconf = Number.isFinite(toNum(vp.visual_confidence)) && vp.visual_confidence !== null ? toNum(vp.visual_confidence) : 0.5;
const vreason = String(vp.visual_reason || '').slice(0, 200);

// ---- weight helpers ----
const round1 = x => Math.round(x * 10) / 10;
const grams = value == null ? null : ((unit === 'kg' || unit === 'кг' || value < 10) ? round1(value * 1000) : value);
const fixDecimal = (s, n) => (s != null && n && s >= n * 3 && s / 10 >= n * 0.5 && s / 10 <= n * 1.5) ? round1(s / 10) : s;
const pos = (x, d) => (Number.isFinite(x) && x > 0 ? x : d);
const tolsOf = c => c ? { u: pos(c.tol_under, DEFAULT_UNDER), o: pos(c.tol_over, DEFAULT_OVER) } : { u: DEFAULT_UNDER, o: DEFAULT_OVER };
// Compare the reading with a norm; subtract the container only when Vision sees one AND it brings the weight closer.
const evaluate = (normTotal, pack, t) => {
  const scale = fixDecimal(grams, normTotal);
  const devNet = (scale - normTotal) / normTotal * 100;
  let tare = 0, dev = devNet;
  if (inContainer && pack > 0) {
    const devTare = (scale - pack - normTotal) / normTotal * 100;
    if (Math.abs(devTare) < Math.abs(devNet)) { tare = pack; dev = devTare; }
  }
  return { scale, tare, net: round1(scale - tare), dev, within: dev >= -t.u && dev <= t.o, u: t.u, o: t.o };
};

// ---- which dish ----
const KINDS = [
  { re: /поке|боул|миск/, cats: ['поке'] },
  { re: /нігірі|нигири/, cats: ['нігірі'] },
  { re: /гункан|човник/, cats: ['гункани'] },
  { re: /рол|макі|маки|сет/, cats: ['роли', 'запечені роли', 'темпура роли', 'макі', 'футомакі', 'сети'] },
];
const kindHit = KINDS.find(k => k.re.test(looks.toLowerCase()));
const kindOk = c => !kindHit || kindHit.cats.includes(c.category);

let card = pre.card || null, source = pre.match_source || '', candidates = [], ev = null;
const readable = grams !== null && vp.readable !== false;
if (readable && !card && (pre.caption_candidates || []).length) {
  const tied = cards.filter(c => pre.caption_candidates.includes(c.dish_id));
  const ok = tied.map(c => ({ c, e: evaluate(c.norm_grams * portions, c.pack_grams, tolsOf(c)) })).filter(x => x.e.within);
  if (ok.length === 1) { card = ok[0].c; source = 'caption'; } else candidates = tied.slice(0, 3);
} else if (!card && (pre.caption_candidates || []).length) {
  candidates = cards.filter(c => pre.caption_candidates.includes(c.dish_id)).slice(0, 3);
}
if (readable && !card && !pre.norm_from_caption && !candidates.length) {
  const sc = cards.map(c => ({ c, e: evaluate(c.norm_grams * portions, c.pack_grams, tolsOf(c)) }));
  const within = sc.filter(x => x.e.within && kindOk(x.c));
  if (within.length === 1) { card = within[0].c; source = 'weight'; }
  else {
    const pool = within.length ? within : sc.filter(x => Math.abs(x.e.dev) <= 25);
    candidates = pool.slice().sort((a, b) => (kindOk(b.c) - kindOk(a.c)) || (Math.abs(a.e.dev) - Math.abs(b.e.dev))).slice(0, 3).map(x => x.c);
  }
}

// ---- verdict ----
let normTotal = null, verdict, recheckWhy = '';
const strongMismatch = !!pre.card && vmatch === false && vconf >= MIN_VISUAL;
const doubtMismatch = !!pre.card && vmatch === false && !strongMismatch;
if (visionEmpty || !readable) verdict = 'UNREADABLE';
else if (card || pre.norm_from_caption) {
  normTotal = (card ? card.norm_grams : pre.norm_from_caption) * portions;
  ev = evaluate(normTotal, card ? card.pack_grams : 0, tolsOf(card));
  if (!card) source = 'norm';
  if (strongMismatch) verdict = 'MISMATCH';
  else if (digitsConf < MIN_DIGITS) { verdict = 'RECHECK'; recheckWhy = 'digits'; }
  else if (Math.abs(ev.dev) > PLAUSIBLE) { verdict = 'RECHECK'; recheckWhy = 'implausible'; }
  else verdict = ev.within ? 'OK' : (ev.dev < 0 ? 'UNDER' : 'OVER');
} else verdict = digitsConf < MIN_DIGITS ? 'RECHECK' : 'LOWCONF';
if (verdict === 'RECHECK' && !recheckWhy) recheckWhy = 'digits';

// ---- reply ----
// Near a tolerance edge show two decimals, so «−2.94%» is not displayed as «−2.9%» next to a «НЕДОВАГА».
const devShown = d => (ev && Math.abs(round1(d)) === (d < 0 ? ev.u : ev.o)) ? Math.round(d * 100) / 100 : round1(d);
const pct = d => (d > 0 ? '+' : '') + devShown(d) + '%';
const title = card ? card.dish_id + ' · ' + card.dish_name + (portions > 1 ? ' × ' + portions : '')
  : (pre.norm_from_caption ? 'Норма з підпису: ' + pre.norm_from_caption + ' г' + (portions > 1 ? ' × ' + portions : '') : '');
const via = { caption: 'за підписом', norm: 'норма з підпису', weight: 'визначено за вагою — якщо страва інша, вкажіть назву або код у підписі' }[source] || '';
const weightLines = () => ev ? [
  'Норма: ' + normTotal + ' г (допуск −' + ev.u + '% / +' + ev.o + '%)',
  'На вагах: ' + ev.scale + ' г' + (ev.tare ? ' (мінус контейнер ' + ev.tare + ' г = ' + ev.net + ' г)' : ''),
  'Відхилення: ' + pct(ev.dev),
] : [];
const candLines = () => candidates.length ? ['Можливо:'].concat(candidates.map(c => '• ' + c.dish_id + ' ' + c.dish_name + ' — ' + c.norm_grams + ' г')) : [];
const doubtLine = doubtMismatch ? '⚠️ Можлива невідповідність фото підпису: ' + (vreason || 'перевірте страву') + '.' : '';
let lines;
if (verdict === 'OK') lines = ['✅ У нормі', title].concat(weightLines(), ['(' + via + ')', doubtLine]);
else if (verdict === 'UNDER') lines = ['⬇️ НЕДОВАГА — порція менша за норму', title].concat(weightLines(), ['(' + via + ')', doubtLine, 'Записано в журнал.']);
else if (verdict === 'OVER') lines = ['⬆️ ПЕРЕВАГА — порція більша за норму', title].concat(weightLines(), ['(' + via + ')', doubtLine, 'Записано в журнал.']);
else if (verdict === 'MISMATCH') lines = ['🚫 Фото не схоже на «' + card.dish_name + '»', 'Причина: ' + (vreason || 'ключові ознаки не збігаються з техкартою')].concat(weightLines(), ['Перевірте страву або підпис. Записано в журнал.']);
else if (verdict === 'RECHECK' && recheckWhy === 'implausible') lines = ['⚠️ Перевірте, будь ласка', title, 'На вагах: ' + ev.scale + ' г при нормі ' + normTotal + ' г (' + pct(ev.dev) + ').',
  'Можливі причини:', '• цифри прочитано неправильно — перезніміть дисплей ближче;', '• на вагах кілька порцій — допишіть «х2»;', '• зважено з посудом — обнуліть ваги з порожнім контейнером (TARE).', doubtLine, 'Записано в журнал як «перевірити».'];
else if (verdict === 'RECHECK') lines = ['⚠️ Цифри на вагах видно нечітко' + (grams != null ? ' (прочитано: ' + grams + ' г)' : '') + '.', 'Перезніміть дисплей ближче, без бліку і розмиття. Записано в журнал як «перевірити».'];
else if (verdict === 'LOWCONF') lines = ['⚠️ Не вдалося визначити позицію', (pre.caption && !pre.card && !pre.norm_from_caption && !(pre.caption_candidates || []).length) ? 'У техкарті не знайдено «' + pre.caption + '».' : '', 'На вагах: ' + (grams != null ? grams + ' г' : '—')].concat(candLines(), ['Вкажіть у підписі назву або код страви (напр. «R01»). Записано в журнал.']);
else if (visionEmpty) lines = ['❓ Сервіс розпізнавання не відповів.', 'Надішліть фото ще раз.'];
else lines = ['❓ Не вдалося зчитати цифри на вагах.', 'Сфотографуйте так, щоб дисплей ваг було чітко видно.', pre.card && vmatch === false ? 'Також фото не схоже на «' + pre.card.dish_name + '»: ' + (vreason || 'ознаки не збігаються') + '.' : '', 'Записано в журнал.'];
if (pre.recheck_of) lines.unshift('🔁 Повторна перевірка цього ж фото (попередня — ' + pre.recheck_of + ').');
// the kitchen this check goes to: the profile's, or the one coded in the caption (checked in «Підпис → кандидат»)
const venueId = pre.venue_id || cook.venue_id || '';
const venueName = pre.venue || cook.venue || '';
// people who can switch kitchens (and anyone whose check went to another kitchen) see where it is logged
if (venueId && (cook.can_switch || venueId !== cook.venue_id)) lines.push('📍 ' + venueId + ' · ' + venueName);
const reply = lines.filter(Boolean).join(N);

// ---- remember the photo (not when Vision returned nothing — the cook should resend the same photo) ----
const now = new Date();
const ts = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Kyiv', dateStyle: 'short', timeStyle: 'medium' }).format(now);
if (pre.photo_uid && !visionEmpty) {
  const sd = $getWorkflowStaticData('global');
  sd.seen = sd.seen || {};
  sd.seen[pre.photo_uid] = { ts, caption: pre.caption || '', final: ['OK', 'UNDER', 'OVER', 'MISMATCH'].includes(verdict) };
  const keys = Object.keys(sd.seen);
  if (keys.length > 500) for (const k of keys.slice(0, keys.length - 500)) delete sd.seen[k];
}

const from = msg.from || {};
const chef = [from.first_name, from.last_name].filter(Boolean).join(' ') + (from.username ? ' (@' + from.username + ')' : '');
const visual_check = pre.card ? (vmatch === true ? 'match' : strongMismatch ? 'mismatch' : doubtMismatch ? 'doubt' : 'unsure') : 'n/a';
return [{ json: {
  venue_id: venueId, venue: venueName,
  ts, date: ts.slice(0, 10), chef, chat_id: String(from.id ?? (msg.chat && msg.chat.id) ?? ''),
  dish_id: card ? card.dish_id : '', dish_name: card ? card.dish_name : (looks || pre.caption || ''),
  match_source: source, portions,
  norm_grams: normTotal, scale_grams: ev ? ev.scale : grams, tare_grams: ev ? ev.tare : null, net_grams: ev ? ev.net : null,
  deviation_pct: ev ? devShown(ev.dev) : null, tol_under_pct: ev ? ev.u : null, tol_over_pct: ev ? ev.o : null,
  verdict, visual_check,
  visual_reason: visionEmpty ? (v.content ? 'vision: відповідь без JSON — ' + String(v.content).slice(0, 80) : 'vision: порожня відповідь') : (vreason || looks),
  digits_confidence: grams != null ? digitsConf : null, photo_uid: pre.photo_uid || '',
  tg_message_id: String(msg.message_id ?? ''), demo: false, reply,
} }];

// ===== report-lib — shared by «Зведення», «Звіт на вимогу» and «Щоденний звіт» (tools/build-workflow.js inlines it) =====
const RL = (() => {
  const INCLUDE_DEMO = true; // the demo history counts in reports; set to false for a real kitchen
  const num = (v) => { if (v === '' || v == null) return null; const n = Number(String(v).replace(',', '.')); return Number.isFinite(n) ? n : null; };
  const isDemo = (r) => r.demo === true || String(r.demo).trim().toUpperCase() === 'TRUE';
  const kyivDate = (d) => new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Kyiv' }).format(d);
  const today = () => kyivDate(new Date());
  const daysAgo = (n) => kyivDate(new Date(Date.now() - n * 86400000));
  // v3 rows still say BRAK — split by the sign of the deviation
  const verdictOf = (r) => { const v = String(r.verdict || ''); if (v !== 'BRAK') return v; const d = num(r.deviation_pct); return d != null && d < 0 ? 'UNDER' : 'OVER'; };

  function filterRows(rows, { venue = null, from = null, includeDemo = INCLUDE_DEMO } = {}) {
    return rows.filter((r) => r && r.verdict
      && (!venue || String(r.venue_id).trim().toUpperCase() === venue)
      && (!from || String(r.date || '').slice(0, 10) >= from)
      && (includeDemo || !isDemo(r)));
  }
  function summarize(rows) {
    const s = { total: rows.length, OK: 0, UNDER: 0, OVER: 0, MISMATCH: 0, RECHECK: 0, LOWCONF: 0, UNREADABLE: 0 };
    const under = [], over = [];
    for (const r of rows) {
      const v = verdictOf(r); if (v in s) s[v]++;
      const d = num(r.deviation_pct);
      if (v === 'UNDER' && d != null) under.push(d);
      if (v === 'OVER' && d != null) over.push(d);
    }
    const avg = (a) => (a.length ? Math.round(a.reduce((x, y) => x + y, 0) / a.length * 10) / 10 : null);
    s.okPct = s.total ? Math.round(s.OK / s.total * 1000) / 10 : null;
    s.avgUnder = avg(under); s.avgOver = avg(over);
    return s;
  }
  function top(rows, keyFn, n = 3) {
    const m = new Map();
    for (const r of rows) {
      const v = verdictOf(r); if (!['UNDER', 'OVER', 'MISMATCH'].includes(v)) continue;
      const k = keyFn(r); if (!k) continue;
      const e = m.get(k) || { k, n: 0, UNDER: 0, OVER: 0, MISMATCH: 0 }; e.n++; e[v]++; m.set(k, e);
    }
    return [...m.values()].sort((a, b) => b.n - a.n).slice(0, n);
  }
  const pct = (v) => (v == null ? '—' : v + '%');
  const sgn = (v) => (v == null ? '' : (v > 0 ? '+' : '') + v + '%');
  const kinds = (e) => [e.UNDER ? '⬇️' + e.UNDER : '', e.OVER ? '⬆️' + e.OVER : '', e.MISMATCH ? '🚫' + e.MISMATCH : ''].filter(Boolean).join(' ');
  // UPD 2026-11-05: ⚠️ (undetermined + unreadable) added so the categories add up to the check count
  const line = (s) => `✅ ${pct(s.okPct)} · ⬇️ ${s.UNDER}${s.UNDER ? ' (' + sgn(s.avgUnder) + ')' : ''} · ⬆️ ${s.OVER}${s.OVER ? ' (' + sgn(s.avgOver) + ')' : ''} · 🚫 ${s.MISMATCH} · 🔎 ${s.RECHECK} · ⚠️ ${s.LOWCONF + s.UNREADABLE}`;
  const LEGEND = '✅ у нормі · ⬇️ недовага · ⬆️ перевага · 🚫 фото ≠ підпис · 🔎 перевірити · ⚠️ не визначено або нечитабельно';
  const dishKey = (r) => [r.dish_id, r.dish_name].filter(Boolean).join(' ');

  function venueReport(rows, title, period) {
    const s = summarize(rows);
    const L = [`📊 ${title} — ${period}`, '', `Перевірок: ${s.total}`,
      `✅ У нормі: ${s.OK} (${pct(s.okPct)})`,
      `⬇️ Недовага: ${s.UNDER}${s.UNDER ? ' · середня ' + sgn(s.avgUnder) : ''}`,
      `⬆️ Перевага: ${s.OVER}${s.OVER ? ' · середня ' + sgn(s.avgOver) : ''}`,
      `🚫 Фото ≠ підпис: ${s.MISMATCH}`, `🔎 Перевірити: ${s.RECHECK}`, `⚠️ Не визначено / ❓ нечитабельно: ${s.LOWCONF + s.UNREADABLE}`];
    const td = top(rows, dishKey);
    if (td.length) { L.push('', 'Страви з відхиленнями:'); for (const e of td) L.push(`• ${e.k}: ${e.n} (${kinds(e)})`); }
    const tc = top(rows, (r) => r.chef);
    if (tc.length) { L.push('', 'Кухарі з відхиленнями:'); for (const e of tc) L.push(`• ${e.k}: ${e.n} (${kinds(e)})`); }
    if (!s.total) L.push('', 'Перевірок за цей період немає.');
    return L.join('\n');
  }
  function networkReport(rows, period) {
    const names = new Map();
    for (const r of rows) if (r.venue_id) names.set(String(r.venue_id).trim().toUpperCase(), String(r.venue || r.venue_id));
    const per = [...names.entries()].sort((a, b) => a[0].localeCompare(b[0]))
      .map(([id, name]) => ({ id, name, s: summarize(rows.filter((r) => String(r.venue_id).trim().toUpperCase() === id)) }));
    const L = [`🏢 Мережа — ${period}`, ''];
    for (const v of per) L.push(`${v.id} ${v.name}: ${v.s.total} перевірок`, '   ' + line(v.s));
    const all = summarize(rows);
    L.push('', `Разом: ${all.total} · ${line(all)}`);
    const withData = per.filter((v) => v.s.total >= 5);
    if (withData.length > 1) {
      // UPD 2026-11-05: a tie names every kitchen that shares the value; when all kitchens tie there is no "lowest"
      const leaders = (f) => { const best = Math.max(...withData.map(f)); return withData.filter((v) => f(v) === best); };
      const worst = leaders((v) => -(v.s.okPct ?? 0));
      const under = leaders((v) => v.s.UNDER / v.s.total);
      const over = leaders((v) => v.s.OVER / v.s.total);
      const H = [];
      if (worst.length === 1) H.push(`Найнижчий % у нормі: ${worst[0].id} ${worst[0].name} (${pct(worst[0].s.okPct)})`);
      else if (worst.length < withData.length) H.push(`Найнижчий % у нормі (${pct(worst[0].s.okPct)}): ${worst.map((v) => v.id + ' ' + v.name).join(', ')}`);
      if (under[0].s.UNDER) H.push('Найбільше недоваги: ' + under.map((v) => `${v.id} ${v.name} (${v.s.UNDER} з ${v.s.total}, середня ${sgn(v.s.avgUnder)})`).join('; '));
      if (over[0].s.OVER) H.push('Найбільше переваги: ' + over.map((v) => `${v.id} ${v.name} (${v.s.OVER} з ${v.s.total}, середня ${sgn(v.s.avgOver)})`).join('; '));
      if (H.length) L.push('', ...H);
    }
    const td = top(rows, dishKey);
    if (td.length) { L.push('', 'Страви з відхиленнями по мережі:'); for (const e of td) L.push(`• ${e.k}: ${e.n} (${kinds(e)})`); }
    if (!all.total) L.push('Перевірок за цей період немає.');
    else L.push('', LEGEND);
    return L.join('\n');
  }
  function periodFrom(text) {
    const t = String(text || '').toLowerCase();
    if (/(all|все|всі|весь)/.test(t)) return { from: null, label: 'за весь час' };
    if (/(^|\s)7(\s|$)|тиж|нед|week/.test(t)) return { from: daysAgo(6), label: 'за 7 днів' };
    return { from: today(), label: 'за сьогодні (' + today() + ')' };
  }
  function venueFrom(text) {
    const m = String(text || '').match(/(?:^|\s)[vв]\s?(\d{1,2})(?!\d)/i);
    return m ? 'V' + Number(m[1]) : null;
  }
  return { INCLUDE_DEMO, filterRows, summarize, venueReport, networkReport, periodFrom, venueFrom, today, verdictOf };
})();
// ===== end report-lib =====

// Code node «Щоденний звіт» — runs on the schedule (22:00 Kyiv). Input: rows of the «Кухарі» sheet;
// the journal comes from «Журнал — для звіту». Output: one message per recipient —
// owners get the network report, managers get their own kitchen. report-lib (RL) is inlined above by the build.
const journal = $('Журнал — для звіту').all().map((i) => i.json);
if (journal.some((r) => r && r.error)) throw new Error('Журнал недоступний');
const people = $input.all().map((i) => i.json).filter((r) => r && r.chat_id);
const isActive = (v) => v === true || ['TRUE', '1', 'ТАК', 'YES'].includes(String(v ?? '').trim().toUpperCase());
const t = RL.today();
const day = RL.filterRows(journal, { from: t });
const out = [];
for (const p of people) {
  if (!isActive(p.active)) continue;
  const role = String(p.role || '').trim().toLowerCase();
  const venueId = String(p.venue_id || '').trim().toUpperCase();
  if (role === 'owner') out.push({ json: { chat_id: String(p.chat_id), reply: ('🗓 Щоденний звіт\n\n' + RL.networkReport(day, 'за сьогодні (' + t + ')')).slice(0, 3900) } });
  else if (role === 'manager' && venueId) {
    const vr = RL.filterRows(journal, { venue: venueId, from: t });
    out.push({ json: { chat_id: String(p.chat_id), reply: ('🗓 Щоденний звіт\n\n' + RL.venueReport(vr, (venueId + ' ' + (p.venue || '')).trim(), 'за сьогодні (' + t + ')')).slice(0, 3900) } });
  }
}
return out;
